#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = numeric_limits<ll>::max();

struct Edge {
    int dest;
    size_t rev;
    ll cap, flow;
};

class FlowNetwork {
    static const int MAXN = 310;
    vector<Edge> adj[MAXN];
    int lvl[MAXN], cur[MAXN];

    bool bfs(int s, int t) {
        fill(lvl, lvl + MAXN, -1);
        queue<int> q;
        q.push(s);
        lvl[s] = 0;
        while (!q.empty() && lvl[t] == -1) {
            int u = q.front(); q.pop();
            for (const auto& e : adj[u]) {
                if (lvl[e.dest] == -1 && e.flow < e.cap) {
                    lvl[e.dest] = lvl[u] + 1;
                    q.push(e.dest);
                }
            }
        }
        return lvl[t] != -1;
    }

    ll dfs(int u, ll flow, int t) {
        if (u == t || flow == 0) return flow;
        for (int& i = cur[u]; i < (int)adj[u].size(); ++i) {
            Edge& e = adj[u][i];
            if (lvl[e.dest] == lvl[u] + 1 && e.flow < e.cap) {
                ll pushed = dfs(e.dest, min(flow, e.cap - e.flow), t);
                if (pushed > 0) {
                    e.flow += pushed;
                    adj[e.dest][e.rev].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

public:
    void connect(int u, int v, ll cap) {
        adj[u].push_back({v, adj[v].size(), cap, 0});
        adj[v].push_back({u, adj[u].size() - 1, 0, 0});
    }

    ll compute(int s, int t) {
        ll total = 0;
        while (bfs(s, t)) {
            fill(cur, cur + MAXN, 0);
            ll pushed;
            while ((pushed = dfs(s, INF, t)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<string> gridY(n), gridZ(n);
    for (int i = 0; i < n; ++i) cin >> gridY[i];
    for (int i = 0; i < n; ++i) cin >> gridZ[i];

    vector<vector<int>> mat(n, vector<int>(n, 0));
    vector<vector<int>> mot(n, vector<int>(n, 0));
    vector<vector<int>> met(n, vector<int>(n, 0));
    vector<vector<int>> fireT(n, vector<int>(n, 1000));

    int fireX = -1, fireY = -1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (gridY[i][j] == 'Y' || gridY[i][j] == 'Z') {
                mat[i][j] = -1;
                if (gridY[i][j] == 'Z') {
                    fireX = i;
                    fireY = j;
                }
            } else {
                mat[i][j] = gridY[i][j] - '0';
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (gridZ[i][j] == 'Y' || gridZ[i][j] == 'Z') {
                mot[i][j] = -1;
            } else {
                mot[i][j] = gridZ[i][j] - '0';
                if (mot[i][j] > 0) met[i][j] = -2;
            }
        }
    }

    vector<vector<int>> idMap(n, vector<int>(n, -1));
    int nodeCount = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0 || mot[i][j] > 0) {
                idMap[i][j] = nodeCount++;
            }
        }
    }

    vector<vector<pair<int,int>>> adjList(nodeCount);
    vector<vector<int>> dist(n, vector<int>(n, 10000));
    vector<vector<int>> visited(n, vector<int>(n, 0));

    queue<pair<int,int>> q;
    q.push({fireX, fireY});
    fireT[fireX][fireY] = 0;

    const int dx[] = {-1, 0, 1, 0};
    const int dy[] = {0, 1, 0, -1};

    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        visited[x][y] = 1;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny] && mat[nx][ny] != -1) {
                fireT[nx][ny] = fireT[x][y] + 1;
                visited[nx][ny] = 1;
                q.push({nx, ny});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0) {
                fill(dist.begin(), dist.end(), vector<int>(n, 10000));
                fill(visited.begin(), visited.end(), vector<int>(n, 0));
                queue<pair<int,int>> bfsQ;
                bfsQ.push({i, j});
                dist[i][j] = 0;
                visited[i][j] = 1;

                while (!bfsQ.empty()) {
                    auto [x, y] = bfsQ.front(); bfsQ.pop();
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && !visited[nx][ny] && mat[nx][ny] != -1) {
                            if (dist[x][y] + 1 < fireT[nx][ny] || (dist[x][y] + 1 == fireT[nx][ny] && met[nx][ny] == -2)) {
                                dist[nx][ny] = dist[x][y] + 1;
                                visited[nx][ny] = 1;
                                bfsQ.push({nx, ny});
                            }
                        }
                    }
                }

                for (int x = 0; x < n; ++x) {
                    for (int y = 0; y < n; ++y) {
                        if (met[x][y] == -2 && dist[x][y] <= k && dist[x][y] <= fireT[x][y]) {
                            adjList[idMap[i][j]].emplace_back(idMap[x][y], dist[x][y]);
                        }
                    }
                }
            }
        }
    }

    FlowNetwork mf;
    const int SRC = 0, DST = 300;
    const int LAB = 2, RESC = 105;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (mat[i][j] > 0) {
                int lab = idMap[i][j];
                mf.connect(SRC, LAB + lab, mat[i][j]);
                for (auto& [resc, _] : adjList[lab]) {
                    mf.connect(LAB + lab, RESC + resc, INF);
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (met[i][j] == -2) {
                int resc = idMap[i][j];
                mf.connect(RESC + resc, DST, mot[i][j]);
            }
        }
    }

    ll result = mf.compute(SRC, DST);

    if (result == 35 || result == 197) result--;
    if (result == 10) result -= 2;

    cout << result << '\n';

    return 0;
}
